--
-- Table structure for table `split_job`
--

DROP TABLE IF EXISTS `split_job`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `split_job` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `job_no` varchar(32) NOT NULL COMMENT '分割作业号 SV+yyyyMMdd+3位当日流水；一条作业=一头白条的整份产出清单',
  `parent_batch_id` bigint NOT NULL COMMENT '所属胴体批次 carcass_batch.id',
  `parent_batch_no` varchar(32) NOT NULL COMMENT '所属胴体批次号（冗余，追溯查询免联表）',
  `pig_id` bigint DEFAULT NULL COMMENT '被分割的那头生猪 id；报文带耳标时精确定位，否则为空（按批次均重对账）',
  `ear_tag_no` varchar(32) DEFAULT NULL COMMENT '耳标号（白条挂钩标签识读结果）',
  `operator` varchar(32) DEFAULT NULL COMMENT '分割操作员（实名）。设备不得代签，缺人转人工',
  `workshop` varchar(64) DEFAULT NULL COMMENT '分割车间',
  `line_no` varchar(32) DEFAULT NULL COMMENT '分割产线/班次',
  `workshop_temp` decimal(4,1) DEFAULT NULL COMMENT '车间温度(℃)',
  `item_count` int NOT NULL DEFAULT '0' COMMENT '本次作业切出的部位条数',
  `total_weight_kg` decimal(8,2) DEFAULT NULL COMMENT '各部位重量合计(kg)',
  `parent_weight_kg` decimal(8,2) DEFAULT NULL COMMENT '对账基准：该头白条重量(kg)',
  `weight_basis` varchar(16) DEFAULT NULL COMMENT '基准来源：PIG=按耳标精确 / BATCH_AVG=批次单头均值 / NONE=无基准（不做对账）',
  `total_yield_rate` decimal(6,2) DEFAULT NULL COMMENT '总出肉率(%) = 各部位合计 / 白条重量 × 100',
  `lean_yield_rate` decimal(6,2) DEFAULT NULL COMMENT '红肉出肉率(%) = 红肉类部位合计 / 白条重量 × 100',
  `check_status` tinyint NOT NULL DEFAULT '0' COMMENT '对账结论：0=通过 1=待人工复核（缺必出部位/总重超上限/总重低于下限）',
  `check_note` varchar(500) DEFAULT NULL COMMENT '对账说明（缺哪些部位、超了多少）；通过时为空',
  `split_time` datetime NOT NULL COMMENT '分割作业时刻',
  `source` varchar(16) DEFAULT 'DEVICE' COMMENT '数据来源：MANUAL/DEVICE',
  `source_ref` varchar(64) DEFAULT NULL COMMENT '来源设备号',
  `raw_payload` json DEFAULT NULL COMMENT '设备原始报文留档',
  `content_hash` char(64) DEFAULT NULL COMMENT '原文内容哈希(SHA-256)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `void_flag` tinyint NOT NULL DEFAULT '0' COMMENT '作废标记：0=有效 1=已作废（MyBatis-Plus 逻辑删除列）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_job_no` (`job_no`),
  KEY `idx_parent` (`parent_batch_id`),
  KEY `idx_split_time` (`split_time`),
  KEY `idx_check` (`check_status`)
) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='分割作业：一头白条的整份产出清单（一次上报产生一条，展开为多条 split_batch）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `split_job`
--

