CREATE TABLE `retail_sale` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `split_batch_id` bigint NOT NULL,
  `transport_id` bigint DEFAULT NULL,
  `receipt_id` bigint DEFAULT NULL,
  `product_qr_code` varchar(64) NOT NULL,
  `store_id` bigint NOT NULL,
  `store_name` varchar(128) DEFAULT NULL,
  `shelf_time` datetime DEFAULT NULL,
  `sell_time` datetime DEFAULT NULL,
  `sell_price` decimal(8,2) DEFAULT NULL,
  `sell_weight_kg` decimal(6,2) DEFAULT NULL,
  `is_activated` tinyint DEFAULT '0',
  `activate_time` datetime DEFAULT NULL,
  `status` tinyint DEFAULT '1',
  `expire_date` date NOT NULL,
  `block_hash` varchar(128) DEFAULT NULL,
  `source` varchar(16) DEFAULT 'MANUAL' COMMENT 'æ•°æ®æ¥æº MANUAL/DEVICE/API/IMPORT',
  `source_ref` varchar(64) DEFAULT NULL COMMENT 'æ¥æºè®¾å¤‡å·/å•æ®å·',
  `raw_payload` json DEFAULT NULL COMMENT 'è®¾å¤‡åŽŸå§‹æŠ¥æ–‡',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `void_flag` tinyint NOT NULL DEFAULT '0' COMMENT '0=有效 1=已作废',
  `void_reason` varchar(500) DEFAULT NULL COMMENT '作废理由（必填）',
  `void_operator` varchar(128) DEFAULT NULL COMMENT '作废操作人（实名）',
  `void_time` datetime DEFAULT NULL COMMENT '作废时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_qr` (`product_qr_code`),
  KEY `idx_status_expire` (`status`,`expire_date`),
  KEY `idx_store` (`store_id`),
  KEY `idx_batch` (`split_batch_id`),
  KEY `idx_transport` (`transport_id`),
  KEY `idx_receipt` (`receipt_id`),
  KEY `idx_void_flag` (`void_flag`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='é›¶å”®ç»ˆç«¯äº§å“';
