INSERT INTO `ingest_device` VALUES (1,'TEMP-001','冷藏车温度探头 京A·12345','TEMPERATURE','一号冷藏车车厢','京A·12345',300,'dev-key-temp-001',1,'2026-10-11 17:34:02','车载温控终端，30秒上报一次','2026-09-21 16:49:48'),(2,'TEMP-002','冷库温度探头 成品库A','TEMPERATURE','分割车间成品库A',NULL,NULL,'dev-key-temp-002',1,NULL,'冷库固定探头，5分钟上报一次','2026-09-21 16:49:48'),(3,'TEMP-003','冷藏车温度探头 京A·12346','TEMPERATURE','二号冷藏车车厢','京A·12346',300,'dev-key-temp-003',1,'2026-10-10 13:59:12','车载温控终端','2026-09-21 16:49:48'),(4,'GATE-001','入场门禁地磅','ENTRY','屠宰场北门',NULL,NULL,'dev-key-gate-001',1,'2026-10-11 17:39:14','车牌识别 + 地磅称重','2026-09-21 16:49:48'),(5,'RFID-001','耳标识读器','ENTRY','屠宰场入场通道',NULL,NULL,'dev-key-rfid-001',1,'2026-10-04 17:33:42','读取电子耳标，带出来源养殖场','2026-09-21 16:49:48'),(6,'CERT-001','检疫证核验终端','ENTRY','屠宰场入场通道',NULL,NULL,'dev-key-cert-001',1,'2026-10-10 15:19:22','扫描检疫证二维码核验','2026-09-21 16:49:48'),(7,'READER-001','瘦肉精读数仪','RACTOPAMINE','屠宰场化验室',NULL,NULL,'dev-key-reader-001',1,'2026-10-11 17:39:14','胶体金读数仪，串口输出结果','2026-09-21 16:49:48'),(8,'POS-001','门店收银机 示范一店','SALE','示范一店门店',NULL,NULL,'dev-key-pos-001',1,'2026-10-04 16:35:52','扫码即激活+售出','2026-09-21 16:49:48'),(9,'PDA-001','门店签收PDA 示范一店','RECEIPT','示范一店收货口',NULL,NULL,'dev-key-pda-001',1,'2026-10-04 16:35:52','扫码签收 + 冷柜测温','2026-09-21 16:49:48'),(10,'SHELF-001','门店冷柜温度探头','RECEIPT','示范一店冷柜',NULL,NULL,'dev-key-shelf-001',1,NULL,'签收环节温度采集','2026-09-21 16:49:48'),(11,'TAG-W001','耳标读写器 示范一号舍','TAG','示范养殖场一号舍入口',NULL,NULL,'dev-key-tag-001',1,'2026-10-11 17:39:14','佩戴耳标即建档；耳标必须人工佩戴，设备只记录身份与归属','2026-09-22 18:37:54'),(12,'INJ-001','智能免疫注射器','VACCINE','示范养殖场兽医室',NULL,NULL,'dev-key-inj-001',1,'2026-10-10 15:19:24','自动记录剂量/时间；疫苗批号靠扫码，缺批号拒绝入库','2026-09-22 18:37:54'),(13,'STATION-001','屠宰检验工位终端','INSPECTION','屠宰场检验工位',NULL,NULL,'dev-key-station-001',1,'2026-10-11 17:39:14','兽医判定+终端录入；判定权在人，终端只当\"笔\"','2026-09-22 18:37:54'),(14,'STAMPER-001','胴体自动盖章机','STAMP','屠宰场盖章工位',NULL,NULL,'dev-key-stamper-001',1,'2026-10-11 17:39:14','检验合格才准打章，授权兽医必填','2026-09-22 18:37:54'),(15,'SPLIT-001','分割线扫码称重台','SPLIT','分割车间一号线',NULL,NULL,'dev-key-split-001',1,'2026-10-11 17:38:03','扫白条钩标签自动建分割批次，批次号系统生成','2026-09-22 18:37:54'),(16,'QSCAN-001','产地检疫证扫码登记终端','QUARANTINE','示范养殖场检疫申报点',NULL,NULL,'dev-key-qscan-001',1,'2026-10-11 17:39:14','扫检疫单二维码带出证号/耳标/签发机构/有效期/官方兽医，人工核对后登记；只搬运证面信息，不产生检疫结论','2026-10-08 12:26:57'),(17,'EXITSCALE-001','出栏口称重登记地磅','EXIT_APPLY','示范养殖场出栏通道',NULL,NULL,'dev-key-exitscale-001',1,'2026-10-11 17:39:14','猪只走出栏口时自动识别耳标并称重，直接生成出栏申报；目标屠宰场由人工确认后补录，缺去向则转待人工确认','2026-10-08 13:16:01'),(18,'BATCH-001','屠宰线胴体称重分拣台','BATCH','示范定点屠宰场 白条分拣线',NULL,NULL,'dev-key-batch-001',1,'2026-10-11 17:39:14','白条下线时识读挂钩标签并过磅，系统按「屠宰场 + 屠宰日」自动归集成胴体批次；批次号由系统生成，设备不上报批次号','2026-10-08 20:20:49'),(20,'LOADER-001','1号装车位（车牌识别相机 + 扫码枪）','LOAD','示范定点屠宰场 冷库 1号装车位',NULL,NULL,'dev-key-loader-001',1,'2026-10-11 19:48:11','装车口的点位口径：相机与扫码枪共同构成一次「装车出场」事件，所以是**一个通道**（LOAD），但不是**一台设备** —— 相机面朝车道、扫码枪在装卸位，安装位置与故障模式各不相同，报文里用 vehicleSource 标注车牌来源。此处**没有读卡器**：现场只在上车那一刻刷一次卡，司机身份由车载终端（DEPART 通道）确认，所以装车报文的司机可留空、且不应携带卡号（带了按结构性拒绝挡下）。目的地不由设备决定，匹配不上转人工。','2026-10-09 17:10:23'),(22,'ORDER-TERM-001','商家选购终端（订单接入）','ORDER','外部系统（商超/门店下单端）',NULL,NULL,'dev-key-order-001',1,'2026-10-11 17:36:50','第 16 条通道：接收外部系统的选购/订单事实，转成「待排车的发货计划」。落点不是既成事实而是决策单，所以 handler 里不做业务判定，排车仍由人决定。同一 order_no 重复推送幂等；不含任何金额字段。','2026-10-09 22:08:40'),(24,'DEPART-001','车载终端（京A·12345）','DEPART','一号冷藏车驾驶室（司机上车刷卡 / 到站刷卡）','京A·12345',NULL,'dev-key-depart-001',1,'2026-10-11 19:52:10','车载终端：同一台设备承担两个通道 —— 发车确认（司机上车刷卡，把责任落到具体人）与到站刷卡确认（每刷一次推进一站）。两通道同组，见 IngestChannel.deviceGroup()。装在本行 vehicle_no 记的那台车上（结构化绑定，不靠设备名里的字符串猜）。','2026-10-10 14:30:31'),(25,'DEPART-003','车载终端（京A·12346）','DEPART','二号冷藏车驾驶室（司机上车刷卡 / 到站刷卡）','京A·12346',NULL,'dev-key-depart-003',1,'2026-10-11 19:46:36','车载终端：同上，装在本行 vehicle_no 记的那台车上。','2026-10-10 14:30:31'),(30,'ARRIVE-001','车载终端（通用 · 演示 / 回归）','ARRIVE','演示 / 回归用（不绑车，车牌以报文为准）',NULL,NULL,'dev-key-arrive-001',1,'2026-10-11 19:48:11','车载终端：同上，一台设备承担两个通道。本行**有意不绑车牌** —— 它是演示 / 回归用的通用终端，车牌由报文里的 vehicleNo 带入（接入层 vehicleOf()：报文优先、台账兜底）；「报文与台账都没有车牌 → 拒绝」这条红线用例也正靠它成立。真机上的车载终端都绑车，见 DEPART-001 / DEPART-003。','2026-10-10 17:14:46');
